<script lang="ts">
 import UnsavedChanges from '$lib/shared/presentation/ui/UnsavedChanges.svelte';
 import {queueDepth,queueReturn} from '$lib/shared/presentation/queue-context';
 import {tick} from 'svelte';
 import {page} from '$app/state';
 import QueueFilters from '$lib/shared/presentation/ui/QueueFilters.svelte';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {copy,noticeText,failureCode} from '$lib/shared/presentation/copy';
 const {locale,change:changeLanguage}=useLocale();
 import {reportCategories} from './messages';
 const categoryNames=$derived(reportCategories($locale));
 import {onMount} from 'svelte';
 import type {CommunityGateway,ModerationReport} from '../application/community';
 import {receiveReports,resolveReport,type ReportQueue} from '../application/report-queue';
 import {validReport} from '../domain/content';
 let {gateway}:{gateway:CommunityGateway}=$props();
 let account=$state<string|null>(null),queue=$state<ReportQueue>({items:[],next:'',hasMore:false}),reasons=$state<Record<string,string>>({}),busy=$state(false),message=$state(''),loadError=$state(''),retryAfter='';
 let depth=$state(1);
 let activeReport=$state(''),showInspector=$state(false),reportPanel=$state<HTMLElement>();let reportTrigger:HTMLButtonElement|undefined;
 const inspectedReport=$derived(queue.items.find(item=>item.id===activeReport)||queue.items[0]);
 async function showReport(id:string,trigger:HTMLButtonElement){activeReport=id;showInspector=true;reportTrigger=trigger;await tick();reportPanel?.focus({preventScroll:true});if(window.innerWidth<1000)reportPanel?.scrollIntoView({block:'start'});}
 async function hideReport(){showInspector=false;await tick();if(reportTrigger?.isConnected)reportTrigger.focus();}

 const dirty=$derived(Object.values(reasons).some(reason=>reason.trim()!==''));
 async function load(after=''){busy=true;loadError='';message='';retryAfter=after;try{account=await gateway.account();if(!account){loadError="login_required";return;}const result=await gateway.reports(account,after,page.url.searchParams.get('team')||'',page.url.searchParams.get('kind')||'');queue=receiveReports(queue,result,!!after);if(after)depth++;else depth=1;}catch(failure){loadError=failureCode(failure);}finally{busy=false;}}
 onMount(()=>{void (async()=>{await load();const wanted=queueDepth(page.url);for(let step=1;step<wanted&&queue.hasMore&&!loadError;step++)await load(queue.next);const requested=page.url.hash.replace('#queue-','');if(queue.items.some(item=>item.id===requested)){activeReport=requested;showInspector=true;}await tick();if(page.url.hash)document.getElementById(page.url.hash.slice(1))?.scrollIntoView();})();});
 async function decide(item:ModerationReport,status:string){if(!account||!validReport(reasons[item.id]||'')){message="decision_reason";return;}busy=true;try{await gateway.resolve(account,item.id,status,reasons[item.id]);queue=resolveReport(queue,item.id);delete reasons[item.id];message="decision_saved";}catch(failure){message=failureCode(failure);}finally{busy=false;}}
 async function visibility(item:ModerationReport,hidden:boolean){if(!account||!validReport(reasons[item.id]||'')){message="action_reason";return;}busy=true;try{await gateway.visibility(account,item.targetId,hidden,reasons[item.id]);queue={...queue,items:queue.items.map(report=>report.targetType==='comment'&&report.targetId===item.targetId?{...report,commentHidden:hidden}:report)};message=hidden?"comment_hidden":"comment_restored";}catch(failure){message=failureCode(failure);}finally{busy=false;}}
</script>
<UnsavedChanges {dirty}/>
<svelte:head><title>{copy($locale,"Шағымдар — Qmanga")}</title><meta name="robots" content="noindex"/></svelte:head>
<a class="auth-link" href={page.url.pathname.startsWith('/admin')?'/admin/moderation':'/moderation'}>{copy($locale,"Жарияланымдарды тексеру")}</a><h1>{copy($locale,"Шағымдар")}</h1>{#if message}<p class="form-message" role="status">{noticeText($locale,message)}</p>{/if}
<QueueFilters kinds={[{value:'title',kk:'Тайтл',ru:'Тайтл'},{value:'release',kk:'Тарау',ru:'Глава'},{value:'page',kk:'Бет',ru:'Страница'},{value:'comment',kk:'Пікір',ru:'Комментарий'}]}/>
{#if loadError}<p class="form-message" role="alert">{noticeText($locale,loadError)}</p><button class="button subtle" disabled={busy} onclick={()=>load(retryAfter)}>{text($locale,'Қайталау','Повторить')}</button>{/if}
<div class="reports-workbench"><section class="reports-list" aria-label={text($locale,'Шағымдар кезегі','Очередь обращений')}>{#each queue.items as item (item.id)}<button class="report-summary" class:chosen={inspectedReport?.id===item.id} aria-pressed={inspectedReport?.id===item.id} onclick={event=>void showReport(item.id,event.currentTarget)}><span class="report-summary-heading"><strong>{item.titleName||text($locale,'Қолжетімсіз тайтл','Тайтл недоступен')}</strong><span>{categoryNames[item.category]||item.category}</span></span><span class="report-excerpt">{item.reason}</span><time datetime={item.createdAt}>{new Date(item.createdAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ',{timeZone:'UTC'})}</time></button>{:else}{#if !busy&&!loadError}<p class="empty-state">{copy($locale,'Қаралмаған шағым жоқ.')}</p>{/if}{/each}</section><aside class="reports-inspector" class:visible={showInspector} bind:this={reportPanel} tabindex="-1" aria-label={text($locale,'Шағым мәліметтері','Сведения обращения')}><button class="button subtle report-back" onclick={()=>void hideReport()}>{text($locale,'Кезекке оралу','Вернуться к очереди')}</button>{#each queue.items.filter(item=>item.id===inspectedReport?.id) as item}<article id={'queue-'+item.id}>
 <header><h2>{item.titleName||text($locale,'Қолжетімсіз тайтл','Тайтл недоступен')}</h2><span>{categoryNames[item.category]||item.category}</span><time datetime={item.createdAt}>{new Date(item.createdAt).toLocaleString($locale==='ru'?'ru-RU':'kk-KZ')}</time></header>
 <nav aria-label={text($locale,'Нысанға өту','Перейти к объекту')}>
 {#if item.titleSlug}<a class="auth-link" href={'/titles/'+encodeURIComponent(item.titleSlug)}>{text($locale,'Тайтл','Тайтл')}</a>{/if}
 {#if item.teamSlug}<a class="auth-link" href={'/teams/'+encodeURIComponent(item.teamSlug)}>{item.teamName}</a>{/if}
 {#if item.releaseId}<a class="auth-link" href={'/read/'+encodeURIComponent(item.releaseId)+(item.revisionId?'?preview='+encodeURIComponent(item.revisionId)+'&page='+encodeURIComponent(item.targetType==='page'?item.targetId:item.pageId)+'&returnTo='+encodeURIComponent(queueReturn(page.url,depth,item.id)):'')}>{text($locale,'Тарау','Глава')} {item.chapterLabel}{#if item.pagePosition} · {text($locale,'Бет','Страница')} {item.pagePosition}{/if}</a>{/if}
 {#if item.targetType==='comment'&&item.releaseId}<a class="auth-link" href={'/read/'+encodeURIComponent(item.releaseId)+'?comment='+encodeURIComponent(item.targetId)+'&returnTo='+encodeURIComponent(queueReturn(page.url,depth,item.id))}>{text($locale,'Пікір','Комментарий')}</a>{/if}
 {#if item.targetType==='comment'&&item.titleSlug&&!item.releaseId}<a class="auth-link" href={'/titles/'+encodeURIComponent(item.titleSlug)+'?tab=comments&comment='+encodeURIComponent(item.targetId)+'&returnTo='+encodeURIComponent(queueReturn(page.url,depth,item.id))}>{text($locale,'Талқылау','Обсуждение')}</a>{/if}
 </nav>
 {#if item.targetType==='comment'}<blockquote><strong>{item.commentAuthor||text($locale,'Оқырман','Читатель')}</strong><p>{item.commentDeleted?text($locale,'Пікір өшірілген','Комментарий удалён'):item.commentBody||text($locale,'Мәтін қолжетімсіз','Текст недоступен')}</p>{#if item.commentHidden}<small>{text($locale,'Жасырылған','Скрыт')}</small>{/if}</blockquote>{/if}
 <p>{item.reason}</p>{#if item.contactEmail}<p>{text($locale,'Байланыс поштасы (расталмаған)','Почта для связи (не подтверждена)')}: {item.contactEmail}</p>{/if}
 {#if item.history.length}<details><summary>{text($locale,'Алдыңғы шешімдер','Предыдущие решения')} ({item.history.length})</summary>{#each item.history as decision}<p><strong>{decision.actorName||text($locale,'Модератор','Модератор')}</strong> · {decision.action==='hide_comment'?text($locale,'Жасырылды','Скрыт'):decision.action==='restore_comment'?text($locale,'Қайта ашылды','Восстановлен'):decision.status==='resolved'?text($locale,'Шешілді','Решено'):decision.status==='dismissed'?text($locale,'Негізсіз','Отклонено'):text($locale,'Шешім','Решение')} · {new Date(decision.createdAt).toLocaleString($locale==='ru'?'ru-RU':'kk-KZ')}<br/>{decision.reason}</p>{/each}</details>{/if}
 <details><summary>{text($locale,'Техникалық деректер','Технические данные')}</summary><dl><dt>{text($locale,'Шағым ID','ID обращения')}</dt><dd>{item.id}</dd><dt>{copy($locale,'Нысан')}</dt><dd>{item.targetType} · {item.targetId}</dd>{#if item.revisionId}<dt>{text($locale,'Нұсқа ID','ID версии')}</dt><dd>{item.revisionId}</dd>{/if}</dl></details>
 <label>{copy($locale,'Модератор шешімінің себебі')}<textarea bind:value={reasons[item.id]} minlength="8" maxlength="2000" rows="3"></textarea></label>
 <div class="actions">{#if item.targetType==='comment'&&!item.commentDeleted}<button class="button subtle" disabled={busy||item.commentHidden} onclick={()=>visibility(item,true)}>{copy($locale,'Пікірді жасыру')}</button><button class="button subtle" disabled={busy||!item.commentHidden} onclick={()=>visibility(item,false)}>{copy($locale,'Қайта ашу')}</button>{/if}<button class="button primary" disabled={busy} onclick={()=>decide(item,'resolved')}>{copy($locale,'Шешілді')}</button><button class="button subtle" disabled={busy} onclick={()=>decide(item,'dismissed')}>{copy($locale,'Негізсіз')}</button></div>
 </article>{:else}{#if !busy&&!loadError}<p class="empty-state">{queue.hasMore?text($locale,'Жүктелген шағымдар қаралды. Келесі бетті ашыңыз.','Загруженные обращения рассмотрены. Откройте следующую страницу.'):copy($locale,'Қаралмаған шағым жоқ.')}</p>{/if}{/each}</aside></div>{#if queue.hasMore}<button class="button" disabled={busy} onclick={()=>load(queue.next)}>{copy($locale,"Тағы жүктеу")}</button>{/if}{#if busy}<p role="status">{copy($locale,"Жүктелуде…")}</p>{/if}
<style>header{display:flex;flex-wrap:wrap;gap:8px;align-items:baseline}header h2{flex-basis:100%}time{font-size:12px;color:var(--muted)}nav{display:flex;flex-wrap:wrap;gap:16px}blockquote{margin:12px 0;padding:12px 16px;border-left:3px solid var(--line)}summary{min-height:44px;display:flex;align-items:center;cursor:pointer}details{margin-bottom:12px}h1{font-size:26px}h2{font-size:20px}article{padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel);margin-block:12px;min-width:0}article p{white-space:pre-wrap;overflow-wrap:anywhere;margin:12px 0}dl{font-size:13px}dd{margin:0;overflow-wrap:anywhere}label{display:grid;gap:8px;font-size:14px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}.reports-workbench{display:grid;gap:24px;margin-top:20px;align-items:start}.reports-list{display:grid;gap:12px;min-width:0}.report-summary{display:grid;gap:10px;padding:20px;text-align:start;color:var(--text);background:var(--panel);border:1px solid var(--line);border-radius:12px;min-width:0;width:100%}.report-summary.chosen{background:var(--raised)}.report-summary-heading{display:flex;justify-content:space-between;align-items:start;gap:12px;font-size:14px;overflow-wrap:anywhere}.report-summary-heading>span{font-size:11px;color:var(--muted);flex:none}.report-excerpt{display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:13px;color:var(--muted);overflow-wrap:anywhere}.report-summary time{font-size:11px;color:var(--muted)}.reports-inspector{min-width:0;scroll-margin-top:80px}.reports-inspector article{max-width:none;margin:0;padding:24px}.reports-inspector header{flex-wrap:wrap;gap:10px}.reports-inspector h2{font-size:18px}.reports-inspector nav{display:flex;flex-wrap:wrap;gap:6px}.reports-inspector nav a{min-height:44px;display:flex;align-items:center;font-size:13px}.reports-inspector label{font-size:13px}.reports-inspector .actions .button{font-size:12px}.report-back{margin-bottom:12px}@media(min-width:1000px){.reports-workbench{grid-template-columns:minmax(0,1fr) minmax(300px,1fr)}.reports-inspector{position:sticky;top:88px}.report-back{display:none}}@media(max-width:999px){.reports-inspector{display:none}.reports-inspector.visible{display:block}.reports-inspector article{padding:16px}}
 </style>
